+//! Finite witnesses, sharing estimates, and definition costs in the input grammar.
+use super::*;
+
+impl<Op: Arity + Clone + Debug + Ord + Display> Grammar<Op> {
+    pub(super) fn new<A: Analysis<AstNode<Op>>>(
+        graph: &EGraph<AstNode<Op>, A>,
+        co: &CoOccurrences,
+    ) -> Self
+    where
+        AstNode<Op>: Language,
+    {
+        let mut ids = graph.classes().map(|c| c.id).collect::<Vec<_>>();
+        ids.sort_unstable();
+        let n = ids.len();
+        let mut index = vec![0; ids.last().map_or(0, |&id| usize::from(id) + 1)];
+        for (i, &id) in ids.iter().enumerate() {
+            index[usize::from(id)] = i;
+        }
+        let mut symbols = Vec::new();
+        let mut symbol_ids = BTreeMap::new();
+        let mut rules = Vec::new();
+        let mut by_class = vec![vec![]; n];
+        let mut parents = vec![vec![]; n];
+        let mut repeated = Vec::with_capacity(n);
+        for (out, &id) in ids.iter().enumerate() {
+            repeated.push(co.may_co_occur(id, id));
+            for node in graph[id].iter() {
+                let op = *symbol_ids.entry(node.operation()).or_insert_with(|| {
+                    let op = node.operation();
+                    let name = op.to_string();
+                    let local = name.strip_prefix('$').and_then(|s| s.parse::<usize>().ok());
+                    let library = name.strip_prefix('l').and_then(|s| s.parse::<usize>().ok());
+                    symbols.push(Symbol {
+                        op: op.clone(),
+                        binder: usize::from(name == "lambda" || name == "λ"),
+                        application: name == "@" || name == "apply",
+                        local: local.map_or(0, |i| i.saturating_add(1).min(INF)),
+                        library,
+                    });
+                    symbols.len() - 1
+                });
+                let args: Children = node.iter().map(|&id| index[usize::from(graph.find(id))]).collect();
+                for &arg in &args {
+                    parents[arg].push(rules.len());
+                }
+                by_class[out].push(rules.len());
+                rules.push(Rule { op, args, out });
+            }
+        }
+        let mut costs = vec![INF; n];
+        loop {
+            let mut changed = false;
+            for r in &rules {
+                let cost = sum_cost(&r.args, &costs);
+                if cost < costs[r.out] {
+                    costs[r.out] = cost;
+                    changed = true;
+                }
+            }
+            if !changed { break; }
+        }
+        let mut order: Vec<_> = (0..n).collect();
+        order.sort_unstable_by_key(|&i| (costs[i], i));
+        let mut roots = Vec::new();
+        for i in 0..n {
+            if parents[i].iter().all(|&r| rules[r].out == i) {
+                roots.push(i);
+                // Multiplicity is unknown once equal roots have merged.
+                // Give shared source classes extra weight in the estimate.
+                if repeated[i] {
+                    roots.extend([i, i, i]);
+                }
+            }
+        }
+        let deterministic = by_class.iter().all(|rules| rules.len() == 1);
+        let mut locals = vec![0usize; n];
+        let mut chosen = vec![None; n];
+        let mut containing_lib = vec![false; n];
+        for &i in &order {
+            chosen[i] = by_class[i].iter().copied()
+                .find(|&ri| sum_cost(&rules[ri].args, &costs) == costs[i]);
+            if let Some(ri) = chosen[i] {
+                let r = &rules[ri];
+                locals[i] = r.args.iter().map(|&c| locals[c]).max().unwrap_or(0)
+                    .saturating_sub(symbols[r.op].binder).max(symbols[r.op].local);
+                containing_lib[i] = symbols[r.op].library.is_some()
+                    || r.args.iter().any(|&j| containing_lib[j]);
+            }
+        }
+        // Within a cycle retain transitions that decrease the size of
+        // the shortest witness. This leaves at least one finite derivation
+        // per productive state while allowing large acyclic alternatives.
+        let mut excess: Vec<_> = rules.iter().map(|r| sum_cost(&r.args, &costs) - costs[r.out]).collect();
+        let mut seen = vec![n; n];
+        let mut stack = Vec::new();
+        for i in 0..n {
+            if by_class[i].iter().all(|&ri| rules[ri].args.iter().all(|&a| costs[a] < costs[i])) {
+                continue;
+            }
+            stack.push(i);
+            seen[i] = i;
+            while let Some(c) = stack.pop() {
+                for &ri in &parents[c] {
+                    let j = rules[ri].out;
+                    if seen[j] != i {
+                        seen[j] = i;
+                        stack.push(j);
+                    }
+                }
+            }
+            for &ri in &by_class[i] {
+                if rules[ri].args.iter().any(|&a| seen[a] == i && costs[a] >= costs[i]) {
+                    excess[ri] = INF;
+                }
+            }
+        }
+        let mut reachable = vec![false; n];
+        let mut pending = roots.clone();
+        for &i in order.iter().rev() {
+            while let Some(j) = pending.pop() {
+                if reachable[j] { continue; }
+                reachable[j] = true;
+                for &ri in &by_class[j] {
+                    pending.extend(rules[ri].args.iter().copied());
+                }
+            }
+            // A source component can consist entirely of a cycle.
+            if !reachable[i] && costs[i] < INF && parents[i].iter().all(|&ri| excess[ri] == INF) {
+                roots.push(i);
+                pending.push(i);
+            }
+        }
