+        // inferred roots must also be reachable from another program.
+        for &i in order.iter().rev() {
+            if repeated[i] && locals[i] == 0 && frequency[i] < 2 && costs[i] < INF {
+                roots.push(i);
+                if frequency[i] == 0 { roots.push(i); }
+                frequency = occurrence_bounds(&rules, &parents, &by_class, &roots);
