+        let app = symbols.iter().position(|s| s.application);
+        let variables = symbols.iter().enumerate().filter(|(_, s)| s.local > 0)
+            .map(|(i, s)| (s.local - 1, i)).collect();
+        Self { symbols, rules, by_class, parents, costs, order, roots, repeated,
+            deterministic, frequency, locals, copies, excess, containing_lib, lookup, lambda, app, variables }
+    }
+}
+
+// A parameter can pay for itself inside a single match when the same
+// large argument occurs in several places. Identify these cuts on a
+// minimum-cost witness of each class without expanding cycles.
+pub(super) fn repeated_arguments(costs: &[usize], chosen: &[Option<usize>], rules: &[Rule]) -> Vec<Children> {
+    let n = costs.len();
+    let mut result = vec![Children::new(); n];
+    let mut last = vec![n; n];
+    let mut stack = Vec::new();
+    for site in 0..n {
+        if !(8..=320).contains(&costs[site]) { continue; }
+        stack.push(site);
+        while let Some(i) = stack.pop() {
+            if costs[i] < 4 { continue; }
+            if last[i] == site {
+                if !result[site].contains(&i) { result[site].push(i); }
+            }
+            last[i] = site;
+            if let Some(ri) = chosen[i] {
+                stack.extend(rules[ri].args.iter().copied());
+            }
+        }
+    }
+    result
+}
+
+// Counting all alternatives gives an upper bound on occurrences in any
+// one extraction. Classes reachable through a cycle retain an open bound.
+fn occurrence_bounds(rules: &[Rule], parents: &[Vec<usize>], by_class: &[Vec<usize>],
+        roots: &[usize]) -> Vec<usize> {
+    let n = parents.len();
+    let mut incoming: Vec<_> = parents.iter().map(Vec::len).collect();
+    let mut queue: Vec<_> = (0..n).filter(|&i| incoming[i] == 0).collect();
+    let mut counts = vec![0usize; n];
+    for &i in roots { counts[i] = counts[i].saturating_add(1); }
+    while let Some(i) = queue.pop() {
+        for &ri in &by_class[i] {
+            for &j in &rules[ri].args {
+                counts[j] = counts[j].saturating_add(counts[i]);
+                incoming[j] -= 1;
+                if incoming[j] == 0 { queue.push(j); }
+            }
+        }
+    }
+    for i in 0..n {
+        if incoming[i] != 0 {
+            counts[i] = usize::MAX;
+        }
+    }
+    counts
+}
+
+// Compute the matching transitions in a local product. Exclusive
+// constructors cannot extend a common pattern of these two witnesses.
+pub(super) fn paired_steps<Op>(g: &Grammar<Op>, a: usize, b: usize) -> Vec<usize> {
+    let mut automaton = Dfta::new();
+    for i in [a, b] {
+        for &ri in &g.by_class[i] {
+            let r = &g.rules[ri];
+            automaton.add_rule((r.op, r.args.len()), 0..r.args.len(), i);
+        }
+    }
+    let paired = automaton.cross_over();
+    let mut ops = Vec::new();
+    if let Some(rules) = paired.get_by_output(&(a, b)) {
+        for ((left, right), _) in rules {
+            if left == right { ops.push(left.0); }
+        }
+    }
+    ops.sort_unstable();
+    ops.dedup();
+    ops
+}
+
+// Cost a prospective definition in the existing e-graph. Subtrees
+// already present in a class can use its smallest equivalent form.
+#[derive(Clone, Copy)]
+struct Value {
+    class: Option<usize>,
+    cost: usize,
+}
+
+impl<Op> Grammar<Op> {
+    fn apply(&self, op: Option<usize>, args: &[Value]) -> Value {
+        if let Some(op) = op {
+            let states: Option<Children> = args.iter().map(|v| v.class).collect();
+            if let Some(i) = states.and_then(|states| self.lookup.get(&(op, states)).copied()) {
+                return Value { class: Some(i), cost: self.costs[i] };
+            }
+        }
+        Value { class: None, cost: 1 + args.iter().map(|v| v.cost).sum::<usize>() }
+    }
+
+    fn body(&self, tokens: &mut std::slice::Iter<'_, Token>, depth: usize) -> Value {
+        match *tokens.next().unwrap() {
+            Token::Arg(a) => {
+                let mut value = self.apply(self.variables.get(&(a + depth)).copied(), &[]);
+                for local in (0..depth).rev() {
+                    let arg = self.apply(self.variables.get(&local).copied(), &[]);
+                    value = self.apply(self.app, &[value, arg]);
+                }
+                value
+            }
+            Token::Op(op, n) => {
+                let depth = depth + self.symbols[op].binder;
+                let args: SmallVec<[Value; 2]> = (0..n).map(|_| self.body(tokens, depth)).collect();
+                self.apply(Some(op), &args)
+            }
+        }
+    }
+
+    pub(super) fn definition(&self, pattern: &[Token], actuals: usize, free: usize, wrappers: usize, site: usize) -> usize {
+        if self.deterministic { return 1 + pattern.len() + wrappers + actuals + free; }
+        let mut value = if actuals == 0 {
+            Value { class: Some(site), cost: self.costs[site] }
+        } else {
+            self.body(&mut pattern.iter(), 0)
+        };
+        for _ in 0..actuals + free {
+            value = self.apply(self.lambda, &[value]);
+        }
+        1 + value.cost
+    }
+}
