+//! Candidate generation for a ranked e-graph grammar.
+use crate::{
+    ast_node::{Arity, AstNode, PartialExpr},
+    co_occurrence::CoOccurrences,
+    dfta::Dfta,
+};
+use egg::{Analysis, EGraph, Language, Searcher, Var};
+use smallvec::{smallvec, SmallVec};
+use std::{
+    collections::{BTreeMap, BTreeSet, HashMap},
+    fmt::{Debug, Display},
+};
+
+type Children = SmallVec<[usize; 2]>;
+type Path = SmallVec<[usize; 8]>;
+const INF: usize = usize::MAX / 4;
+const SLACK: usize = 10;
+const SHORTLIST: usize = 32;
+const LOOKAHEAD: usize = 12;
+
+struct Symbol<Op> {
+    op: Op,
+    binder: usize,
+    application: bool,
+    local: usize,
+    library: Option<usize>,
+}
+
+struct Rule {
+    op: usize,
+    args: Children,
+    out: usize,
+}
+
+struct Grammar<Op> {
+    symbols: Vec<Symbol<Op>>,
+    rules: Vec<Rule>,
+    by_class: Vec<Vec<usize>>,
+    parents: Vec<Vec<usize>>,
+    costs: Vec<usize>,
+    order: Vec<usize>,
+    roots: Vec<usize>,
+    repeated: Vec<bool>,
+    frequency: Vec<usize>,
+    locals: Vec<usize>,
+    deterministic: bool,
+    excess: Vec<usize>,
+    containing_lib: Vec<bool>,
+    copies: Vec<Children>,
+    lookup: HashMap<(usize, Children), usize>,
+    lambda: Option<usize>,
+    app: Option<usize>,
+    variables: BTreeMap<usize, usize>,
+}
+
+fn sum_cost(args: &[usize], costs: &[usize]) -> usize {
+    args.iter().fold(1usize, |s, &a| s.saturating_add(costs[a])).min(INF)
+}
+
+#[derive(Clone, Copy, PartialOrd, Ord, PartialEq, Eq)]
+enum Token {
+    Op(usize, usize),
+    Arg(usize),
+}
+
+#[derive(Clone)]
+struct Proposal {
+    score: i64,
+    tokens: Vec<Token>,
+    wrappers: usize,
+    uses: Vec<(usize, Children)>,
+    signature: Vec<(usize, Children)>,
+    call: usize,
+    depths: Children,
+    free: usize,
+}
+
+#[path = "grammar.rs"]
+mod grammar;
+#[path = "search.rs"]
+mod search;
+#[path = "planning.rs"]
+mod planning;
+
+use self::planning::{forecast, residual};
+use self::search::mine;
+
+fn expression<Op: Arity + Clone + Debug>(tokens: &mut std::slice::Iter<'_, Token>,
+        symbols: &[Symbol<Op>], vars: &[Var]) -> PartialExpr<Op, Var> {
+    match *tokens.next().unwrap() {
+        Token::Arg(i) => PartialExpr::Hole(vars[i]),
+        Token::Op(op, arity) => AstNode::new(symbols[op].op.clone(),
+            (0..arity).map(|_| expression(tokens, symbols, vars))).into(),
+    }
+}
+
+pub(super) fn candidates<Op, A>(
+    graph: &EGraph<AstNode<Op>, A>, constants: bool, max_arity: Option<usize>, co: &CoOccurrences,
+) -> BTreeSet<PartialExpr<Op, Var>>
+where
+    Op: Arity + Clone + Debug + Ord + Display,
+    A: Analysis<AstNode<Op>>,
+    AstNode<Op>: Language,
+{
+    if !constants && max_arity == Some(0) {
+        return BTreeSet::new();
+    }
+    let g = Grammar::new(graph, co);
+    let arity = max_arity.unwrap_or(3).min(3);
+    let previous = g.symbols.iter().filter_map(|s| s.library).collect::<Vec<_>>();
+    let keep = if previous.is_empty() { SHORTLIST } else { 10 };
+    let mut miner = mine(&g, arity, constants, keep, 400000, -3);
+    let mut result = BTreeSet::new();
+    let vars: Vec<Var> = (0..arity).map(|i| format!("?x{}", i).parse().unwrap()).collect();
+    if !g.deterministic {
+        // Search the shortlisted patterns without the witness-size bound.
+        // Re-estimate costs and merge equivalent match signatures before
+        // comparing prospective first and second learning steps.
+        let mut ids = graph.classes().map(|c| c.id).collect::<Vec<_>>();
+        ids.sort_unstable();
+        let mut index = vec![0; ids.last().map_or(0, |&id| usize::from(id) + 1)];
+        for (i, &id) in ids.iter().enumerate() { index[usize::from(id)] = i; }
+        let mut distinct = BTreeMap::new();
+        for mut p in std::mem::take(&mut miner.ranked) {
+            let pat = egg::Pattern::from(expression(&mut p.tokens.iter(), &g.symbols, &vars));
+            p.uses.clear();
+            for m in pat.search(graph) {
+                let i = index[usize::from(graph.find(m.eclass))];
+                for sub in m.substs {
+                    p.uses.push((i, vars[..p.depths.len()].iter()
+                        .map(|v| index[usize::from(graph.find(sub[*v]))]).collect()));
+                }
+            }
+            if p.uses.is_empty() { continue; }
+            p.uses.sort_unstable();
+            p.uses.dedup();
+            let def = g.definition(&p.tokens, p.depths.len(), p.free, p.wrappers, p.uses[0].0);
+            miner.relax(p.uses.iter().map(|(i, args)| (*i, args)), p.call);
+            p.score = miner.gain(def);
+            p.signature = p.uses.clone();
+            for (_, args) in &mut p.signature { args.sort_unstable(); }
+            p.signature.sort_unstable();
+            let entry = distinct.entry(p.signature.clone()).or_insert_with(|| p.clone());
+            if (p.score, std::cmp::Reverse(p.call)) > (entry.score, std::cmp::Reverse(entry.call)) {
+                *entry = p;
+            }
+        }
+        miner.ranked = distinct.into_values().collect();
+        miner.ranked.sort_by_key(|p| std::cmp::Reverse(p.score));
+    }
+    let mut predicted = Vec::new();
+    let mut best = 0;
+    let mut followup = 0;
+    if previous.is_empty() && miner.ranked.len() > 1 && miner.ranked[0].score > 0 {
+        let mut forests = Vec::new();
+        for i in 0..miner.ranked.len() {
+            let p = miner.ranked[i].clone();
+            miner.relax(p.uses.iter().map(|(site, args)| (*site, args)), p.call);
+            let (forest, mapping) = residual(&g, &miner.costs, &p);
+            miner.reset();
+            let future = forecast(&forest, &mapping, &miner.ranked);
+            predicted.push(p.score + future);
+            forests.push((i, forest, future));
+        }
+        forests.sort_unstable_by_key(|(i, _, _)| (std::cmp::Reverse(predicted[*i]), *i));
+        for (k, (i, mut forest, future)) in forests.into_iter().enumerate() {
+            if k < 6 || i < 3 {
+                forest.index_terms();
+                let next = mine(&forest, arity, constants, 1, 50000, future.max(1));
+                if let Some(next) = next.ranked.first() {
+                    predicted[i] = miner.ranked[i].score + future.max(next.score);
+                }
+            }
+        }
+        for (i, &gain) in predicted.iter().enumerate() {
+            if gain > best && miner.ranked[i].score > 0 {
+                best = gain;
+                followup = gain - miner.ranked[i].score;
+            }
+        }
+    }
+    for (i, p) in miner.ranked.iter().enumerate() {
+        // The fixed selector has the true root list. Keep alternatives
+        // with comparable future savings so it can resolve uncertainty
+        // about the number of occurrences of a shared root.
+        if predicted.is_empty() || predicted.get(i).map_or(false, |s| {
+            s + 1 >= best || (i < LOOKAHEAD && (s - p.score + 1 >= followup || predicted[0] + 1 >= best))
+        }) {
+            result.insert(expression(&mut p.tokens.iter(), &g.symbols, &vars));
+        }
+    }
+
+    // Rewrites assign names by sorted dictionary position. When names
+    // are already in scope, give the occupied positions to distinct
+    // terminal classes. A terminal always costs at most its named call.
+    if !result.is_empty() && (previous.is_empty() || previous.iter().any(|&i| i < result.len())) {
+        let mut leaves = BTreeMap::new();
+        let mut seen = BTreeSet::new();
+        for r in &g.rules {
+            if r.args.is_empty() && g.symbols[r.op].library.is_none() && g.symbols[r.op].local <= 1 {
+                leaves.insert(&g.symbols[r.op].op, r.out);
+            }
+        }
+        let floor = result.iter().next().unwrap().clone();
+        let limit = previous.iter().copied().max().map_or(1, |i| i.saturating_add(1));
+        let mut prefix = Vec::new();
+        for (op, class) in leaves {
+            if prefix.len() >= limit || !constants { break; }
+            let leaf = PartialExpr::Node(AstNode::leaf(op.clone()));
+            if leaf >= floor { break; }
+            if seen.insert(class) { prefix.push(leaf); }
+        }
+        if prefix.len() == limit {
+            result.extend(prefix);
+        } else if let Some(smallest) = previous.iter().min() {
+            result = miner.ranked.iter().take(*smallest).map(|p| {
+                expression(&mut p.tokens.iter(), &g.symbols, &vars)
+            }).collect();
+        }
+    }
+    result
+}
