new file mode 100644
index 0000000..6c1f1c3
--- /dev/null
+++ b/src/learn_extensions/planning.rs
@@ -0,0 +1,169 @@
+//! Estimate the next learning step on the forest left by a proposed library.
+use super::grammar::repeated_arguments;
+use super::*;
+
+// Check which already-discovered templates survive a first extraction.
+// As the residual graph is a DAG with a single form per term, the best
+// cost for each possible second call follows in one bottom-up pass.
+pub(super) fn forecast(g: &Grammar<usize>, mapping: &[Option<usize>], proposals: &[Proposal]) -> i64 {
+    fn matches(g: &Grammar<usize>, i: usize, tokens: &mut std::slice::Iter<'_, Token>,
+            args: &mut [usize]) -> bool {
+        match *tokens.next().unwrap() {
+            Token::Arg(v) => {
+                if args[v] == INF { args[v] = i; }
+                args[v] == i
+            }
+            Token::Op(op, n) => {
+                let node = &g.rules[i];
+                op == node.op && n == node.args.len()
+                    && node.args.iter().all(|&j| matches(g, j, tokens, args))
+            }
+        }
+    }
+
+    let mut best = 0;
+    let mut costs = g.costs.clone();
+    let mut calls = vec![None; costs.len()];
+    let mut sites = Vec::new();
+    for p in proposals {
+        for (site, _) in &p.uses {
+            if let Some(i) = mapping[*site] {
+                if g.frequency[i] == 0 || calls[i].is_some() { continue; }
+                let mut args = Children::from_elem(INF, p.depths.len());
+                if matches(g, i, &mut p.tokens.iter(), &mut args) {
+                    calls[i] = Some(args);
+                    sites.push(i);
+                }
+            }
+        }
+        if sites.is_empty() { continue; }
+        for &i in &g.order {
+            let mut cost = sum_cost(&g.rules[i].args, &costs);
+            if let Some(args) = &calls[i] {
+                cost = cost.min(p.call + args.iter().map(|&j| costs[j]).sum::<usize>());
+            }
+            costs[i] = cost;
+        }
+        let saving: usize = g.roots.iter().map(|&i| g.costs[i] - costs[i]).sum();
+        let definition = 1 + p.tokens.len() + p.depths.len() + p.free + p.wrappers;
+        best = best.max(saving as i64 - definition as i64);
+        for i in sites.drain(..) { calls[i] = None; }
+    }
+    best
+}
+
+// Reconstruct one minimum-cost forest with the proposed function
+// available. Hash-consing restores sharing after calls replace their
+// original matches, including sharing in the argument subtrees.
+pub(super) fn residual<Op>(g: &Grammar<Op>, costs: &[usize], p: &Proposal) -> (Grammar<usize>, Vec<Option<usize>>) {
+    let mut symbols = g.symbols.iter().enumerate().map(|(op, s)| Symbol {
+        op, binder: s.binder, application: s.application, local: s.local, library: s.library,
+    }).collect::<Vec<_>>();
+    let mut symbol = |binder: usize, application: bool, local: usize, library: Option<usize>| {
+        let op = symbols.len();
+        symbols.push(Symbol { op, binder, application, local, library });
+        op
+    };
+    let lambda = g.symbols.iter().position(|s| s.binder == 1)
+        .unwrap_or_else(|| symbol(1, false, 0, None));
+    let app = g.symbols.iter().position(|s| s.application)
+        .unwrap_or_else(|| symbol(0, true, 0, None));
+    let local = g.symbols.iter().position(|s| s.local == 1)
+        .unwrap_or_else(|| symbol(0, false, 1, None));
+    let lib = symbol(0, false, 0, Some(0));
+
+    let mut grammar = Grammar { symbols, rules: vec![], by_class: vec![], parents: vec![],
+        costs: vec![], repeated: vec![], order: vec![], roots: vec![],
+        frequency: vec![], locals: vec![], deterministic: true, copies: vec![], excess: vec![], containing_lib: vec![], lookup: HashMap::new(), lambda: None, app: None, variables: BTreeMap::new() };
+    let mut memo = HashMap::new();
+    let mut add = |op: usize, args: Children| {
+        let key = (op, args);
+        if let Some(&id) = memo.get(&key) { return id; }
+        let i = grammar.rules.len();
+        let args = key.1.clone();
+        memo.insert(key, i);
+        grammar.costs.push(sum_cost(&args, &grammar.costs));
+        grammar.containing_lib.push(grammar.symbols[op].library.is_some()
+            || args.iter().any(|&j| grammar.containing_lib[j]));
+        grammar.locals.push(args.iter().map(|&j| grammar.locals[j]).max().unwrap_or(0)
+            .saturating_sub(grammar.symbols[op].binder).max(grammar.symbols[op].local));
+        grammar.rules.push(Rule { op, args, out: i });
+        i
+    };
+
+    let mut calls = vec![None; costs.len()];
+    for (i, args) in &p.uses {
+        if calls[*i].is_none() && args.iter().fold(p.call, |s, &j| s.saturating_add(costs[j])) == costs[*i] {
+            calls[*i] = Some(args);
+        }
+    }
+    let mut selected = vec![None; costs.len()];
+    let mut order = Vec::new();
+    let mut pending = g.roots.clone();
+    while let Some(i) = pending.pop() {
+        if selected[i].is_some() || costs[i] == INF { continue; }
+        if let Some(ri) = g.by_class[i].iter().copied()
+            .find(|&ri| sum_cost(&g.rules[ri].args, costs) == costs[i]) {
+            pending.extend(g.rules[ri].args.iter().copied());
+            selected[i] = Some(ri);
+        } else if let Some(args) = calls[i] {
+            pending.extend(args.iter().copied());
+            selected[i] = Some(INF);
+        } else {
+            continue;
+        }
+        order.push(i);
+    }
+    order.sort_unstable_by_key(|&i| (costs[i], i));
+    let mut value = vec![None; costs.len()];
+    for i in order {
+        let ri = selected[i].unwrap();
+        if ri < g.rules.len() {
+            let r = &g.rules[ri];
+            value[i] = Some(add(r.op, r.args.iter().map(|&j| value[j].unwrap()).collect()));
+        } else if let Some(args) = calls[i] {
+            let mut f = add(lib, Children::new());
+            for (&j, &depth) in args.iter().zip(&p.depths).rev() {
+                let mut a = value[j].unwrap();
+                for _ in 0..depth { a = add(lambda, smallvec![a]); }
+                f = add(app, smallvec![f, a]);
+            }
+            if p.free != 0 {
+                let a = add(local, Children::new());
+                f = add(app, smallvec![f, a]);
+            }
+            value[i] = Some(f);
+        }
+    }
+    let mut frequency = vec![0usize; grammar.rules.len()];
+    for &root in &g.roots {
+        if let Some(i) = value[root] {
+            grammar.roots.push(i);
+            frequency[i] = frequency[i].saturating_add(1);
+        }
+    }
+    for i in (0..grammar.rules.len()).rev() {
+        for &j in &grammar.rules[i].args {
+            frequency[j] = frequency[j].saturating_add(frequency[i]);
+        }
+    }
+    grammar.repeated = frequency.iter().map(|&f| f > 1).collect();
+    grammar.order = (0..frequency.len()).filter(|&i| frequency[i] != 0).collect();
+    grammar.frequency = frequency;
+    (grammar, value)
+}
+
+
+impl Grammar<usize> {
+    pub(super) fn index_terms(&mut self) {
+        let n = self.rules.len();
+        self.parents = vec![vec![]; n];
+        for r in &self.rules {
+            for &i in &r.args { self.parents[i].push(r.out); }
+        }
+        self.by_class = (0..n).map(|i| vec![i]).collect();
+        self.excess = vec![0; n];
+        let chosen = (0..n).map(Some).collect::<Vec<_>>();
+        self.copies = repeated_arguments(&self.costs, &chosen, &self.rules);
+    }
+}
