+//! Grow common patterns in preorder, keeping a substitution and the remaining
+//! unmatched children for every possible occurrence.
+use super::grammar::paired_steps;
+use super::*;
+
+// A row is a concrete witness for the pattern prefix under construction.
+// The pending subtrees are in reverse preorder, so extending a pattern
+// takes the same stack operation on every witness.
+#[derive(Clone)]
+struct Row {
+    site: usize,
+    todo: Path,
+    actuals: Children,
+    slack: usize,
+}
+
+pub(super) struct Miner<'a, Op> {
+    g: &'a Grammar<Op>,
+    shared: HashMap<(usize, usize), Vec<usize>>,
+    pub(super) ranked: Vec<Proposal>,
+    keep: usize,
+    floor: i64,
+    arity: usize,
+    constants: bool,
+    fuel: usize,
+    pub(super) costs: Vec<usize>,
+    changes: Vec<usize>,
+    queue: Vec<usize>,
+}
+
+impl<'a, Op> Miner<'a, Op> {
+    pub(super) fn relax<'r, I>(&mut self, uses: I, call: usize)
+    where I: Iterator<Item = (usize, &'r Children)> + Clone {
+        let mut pos = 0;
+        loop {
+            let before = self.queue.len();
+            for (site, actuals) in uses.clone() {
+                let cost = actuals.iter().fold(call, |sum, &i| sum.saturating_add(self.costs[i]));
+                self.improve(site, cost);
+            }
+            if self.queue.len() == before { break; }
+            while pos < self.queue.len() {
+                let class = self.queue[pos];
+                pos += 1;
+                for &ri in &self.g.parents[class] {
+                    let r = &self.g.rules[ri];
+                    let c = sum_cost(&r.args, &self.costs);
+                    self.improve(r.out, c);
+                }
+            }
+        }
+    }
+
+    pub(super) fn reset(&mut self) {
+        self.queue.clear();
+        for i in self.changes.drain(..) { self.costs[i] = self.g.costs[i]; }
+    }
+
+    fn score(&mut self, rows: &[Row], call: usize, definition: usize) -> i64 {
+        self.relax(rows.iter().map(|row| (row.site, &row.actuals)), call);
+        self.gain(definition)
+    }
+
+    pub(super) fn gain(&mut self, definition: usize) -> i64 {
+        let mut gain = 0;
+        for &i in &self.g.roots {
+            gain += self.g.costs[i] - self.costs[i];
+        }
+        self.reset();
+        gain as i64 - definition as i64
+    }
+
+    fn possible(&self, rows: &[Row], call: usize, required: usize) -> bool {
+        let mut gain = 0usize;
+        for row in rows {
+            let call = row.actuals.iter().fold(call, |s, &i| s.saturating_add(self.g.costs[i]));
+            let profit = self.g.costs[row.site].saturating_sub(call);
+            gain = gain.saturating_add(self.g.frequency[row.site].saturating_mul(profit));
+            if gain >= required { return true; }
+        }
+        false
+    }
+
+    fn improve(&mut self, site: usize, cost: usize) {
+        if cost < self.costs[site] {
+            if self.costs[site] == self.g.costs[site] { self.changes.push(site); }
+            self.costs[site] = cost;
+            self.queue.push(site);
+        }
+    }
+
+    fn extend(&mut self, rows: Vec<Row>, slots: &mut Path, depths: &mut Children,
+              pattern: &mut Vec<Token>, free: usize, wrappers: usize) {
+        if self.fuel == 0 || rows.is_empty() || pattern.len() > 200 { return; }
+        // Reification passes implicit outer locals after explicit parameters.
+        // A closed body, or one implicit local alone, has unambiguous order.
+        if free > 1 || (free != 0 && !depths.is_empty()) { return; }
+        self.fuel -= 1;
+        if slots.is_empty() {
+            if !self.constants && depths.is_empty() { return; }
+            let call = 1 + depths.len() + depths.iter().sum::<usize>() + 2 * free;
+            let def = self.g.definition(pattern, depths.len(), free, wrappers, rows[0].site);
+            let score = self.score(&rows, call, def);
+            if score >= self.floor && score + def as i64 > 0 && (self.ranked.len() < self.keep || score > self.ranked.last().unwrap().score) {
+                let mut uses = rows.iter().map(|r| (r.site, r.actuals.clone())).collect::<Vec<_>>();
+                uses.sort_unstable();
+                uses.dedup();
+                let mut signature = uses.clone();
+                for (_, args) in &mut signature { args.sort_unstable(); }
+                signature.sort_unstable();
+                if let Some(i) = self.ranked.iter().position(|p| p.signature == signature) {
+                    let other = &self.ranked[i];
+                    if other.score > score || (other.score == score
+                        && (other.call, other.tokens.len()) <= (call, pattern.len())) { return; }
+                    self.ranked.remove(i);
+                }
+                let index = self.ranked.partition_point(|p| p.score >= score);
+                self.ranked.insert(index, Proposal {
+                    score, tokens: pattern.clone(), wrappers, uses, signature, call, depths: depths.clone(), free,
+                });
+                self.ranked.truncate(self.keep);
+            }
+            return;
+        }
+
+        let call = 1 + depths.len() + depths.iter().sum::<usize>() + 2 * free;
+        let mut minimum_def = 1 + pattern.len() + slots.len() + wrappers + depths.len() + free;
+        if depths.is_empty() && free == 0 && !self.g.deterministic {
+            minimum_def = minimum_def.min(1 + rows.iter().map(|r| self.g.costs[r.site]).min().unwrap());
+        }
+        let threshold = if self.ranked.len() == self.keep { self.ranked.last().unwrap().score } else { self.floor };
+        if !pattern.is_empty() && (!self.possible(&rows, call, (minimum_def as i64 + threshold).max(1) as usize)
+            || (!self.g.deterministic && self.score(&rows, call, minimum_def) < threshold)) {
+            return;
+        }
+        let site = rows[0].site;
+        if rows.iter().all(|r| r.site == site) && !self.g.repeated[site] && self.g.copies[site].is_empty() && self.g.by_class[site].len() == 1 { return; }
+        let depth = slots.pop().unwrap();
+        let class = *rows[0].todo.last().unwrap();
+        let varies = rows.iter().any(|r| r.todo.last() != Some(&class));
+        let abstractable = varies || self.g.locals[class] > depth || self.g.containing_lib[class]
+            || (self.g.costs[class] >= 7 && self.g.repeated[class])
+            || (self.g.costs[class] >= 4 && rows.iter().any(|r| self.g.copies[r.site].contains(&class)));
+        if !pattern.is_empty() {
+            for arg in 0..depths.len() {
+                if depths[arg] != depth { continue; }
+                let mut selected = Vec::new();
+                for row in &rows {
+                    if *row.todo.last().unwrap() == row.actuals[arg] {
+                        let mut row = row.clone();
+                        row.todo.pop();
+                        selected.push(row);
+                    }
+                }
+                if !selected.is_empty() {
+                    let subsumes = selected.len() == rows.len() && depth == 0;
+                    pattern.push(Token::Arg(arg));
+                    self.extend(selected, slots, depths, pattern, free, wrappers + 2 * depth);
+                    pattern.pop();
+                    if subsumes {
+                        slots.push(depth);
+                        return;
+                    }
+                }
+            }
+        }
+
+        let mut groups: BTreeMap<(usize, usize), Vec<Row>> = BTreeMap::new();
+        let pair = if rows.len() == 2 && rows[0].site != rows[1].site && varies
+            && !self.g.repeated[rows[0].site] && !self.g.repeated[rows[1].site]
+            && self.g.copies[rows[0].site].is_empty() && self.g.copies[rows[1].site].is_empty() {
+            let b = *rows[1].todo.last().unwrap();
+            if self.g.by_class[class].len() > 1 || self.g.by_class[b].len() > 1 {
+                let key = (class.min(b), class.max(b));
+                if !self.shared.contains_key(&key) {
+                    self.shared.insert(key, paired_steps(self.g, key.0, key.1));
+                }
+                self.shared.get(&key)
+            } else { None }
+        } else { None };
+        for row in &rows {
+            let next = *row.todo.last().unwrap();
+            for &ri in &self.g.by_class[next] {
+                let r = &self.g.rules[ri];
+                if r.args.contains(&next) || self.g.symbols[r.op].library.is_some() { continue; }
+                if pair.map_or(false, |ops| !ops.contains(&r.op)) { continue; }
+                let extra = self.g.excess[ri];
+                if extra > row.slack { continue; }
+                let group = groups.entry((r.op, r.args.len())).or_default();
+                if group.len() >= 16384 { continue; }
+                let mut copy = row.clone();
+                copy.todo.pop();
+                copy.slack -= extra;
+                copy.todo.extend(r.args.iter().rev().copied());
+                group.push(copy);
+            }
+        }
+        for ((op, n), group) in groups {
+            let start = slots.len();
+            slots.resize(start + n, depth + self.g.symbols[op].binder);
+            let free = free.max(self.g.symbols[op].local.saturating_sub(depth));
+            pattern.push(Token::Op(op, n));
+            self.extend(group, slots, depths, pattern, free, wrappers);
+            pattern.pop();
+            slots.truncate(start);
+        }
+        if !pattern.is_empty() && depths.len() < self.arity && abstractable {
+            let mut selected = Vec::new();
+            for row in &rows {
+                let v = *row.todo.last().unwrap();
+                let mut copy = row.clone();
+                copy.todo.pop();
+                copy.actuals.push(v);
+                selected.push(copy);
+            }
+            pattern.push(Token::Arg(depths.len()));
+            depths.push(depth);
+            self.extend(selected, slots, depths, pattern, free, wrappers + 2 * depth);
+            depths.pop();
+            pattern.pop();
+        }
+        slots.push(depth);
+    }
+}
+
+pub(super) fn mine<Op>(g: &Grammar<Op>, arity: usize, constants: bool, keep: usize, fuel: usize, floor: i64) -> Miner<'_, Op> {
+    let rows: Vec<Row> = g.order.iter().filter(|&&i| g.costs[i] <= 320).map(|&site| Row {
+        site, todo: smallvec![site], actuals: Children::new(), slack: (2 * g.costs[site] + SLACK).min(96),
+    }).collect();
+    let mut miner = Miner {
+        g, shared: HashMap::new(), ranked: vec![], keep, floor, arity, constants, fuel,
+        costs: g.costs.clone(), changes: vec![], queue: vec![],
+    };
+    if g.order.len() >= 120 && arity > 1 {
+        miner.arity = 1;
+        miner.fuel = fuel / 6;
+        miner.extend(rows.clone(), &mut smallvec![0], &mut Children::new(), &mut Vec::new(), 0, 0);
+        miner.arity = arity;
+        miner.fuel += fuel - fuel / 6;
+    }
+    miner.extend(rows, &mut smallvec![0], &mut Children::new(), &mut Vec::new(), 0, 0);
+    miner
+}
